from transformers import (
    AutoTokenizer,
    AutoModelForSequenceClassification,
    TrainerCallback,
)
import numpy as np

from setta.cli import Setta
from setta.cli.logger import SettaList


class SettaLossTracker(TrainerCallback):
    def __init__(self, window_size=10):
        self.setta_logger = Setta(
            root_path="working_finetune",
        )
        self.setta_logging_dict = {
            "step": [],
            "loss": [],
            "moving_avg_loss": [],  # New list for moving average
        }
        self.window_size = window_size

    def calculate_moving_average(self, values):
        if len(values) < self.window_size:
            return None
        return sum(values[-self.window_size :]) / self.window_size

    def on_log(self, args, state, control, logs=None, **kwargs):
        if state.is_local_process_zero and logs is not None:
            if "loss" in logs:
                # Record step and loss
                self.setta_logging_dict["step"].append(state.global_step)
                self.setta_logging_dict["loss"].append(logs["loss"])

                # Calculate and record moving average
                moving_avg = self.calculate_moving_average(
                    self.setta_logging_dict["loss"]
                )
                self.setta_logging_dict["moving_avg_loss"].append(moving_avg)

                # Log everything
                self.setta_logger.log(
                    {"training_loss": SettaList(self.setta_logging_dict)},
                    save_to="disk",
                )


def get_tokenize_function(tokenizer, **kwargs):
    def tokenize_function(examples):
        return tokenizer(examples["text"], **kwargs)

    return tokenize_function


def get_compute_metrics(metric):
    def compute_metrics(eval_pred):
        logits, labels = eval_pred
        predictions = np.argmax(logits, axis=-1)
        return metric.compute(predictions=predictions, references=labels)

    return compute_metrics


